import { auth } from "@clerk/nextjs/server"
import type { PermissionKey } from "./permissions"
import type { RoleDefinition } from "./roles"
import { DEFAULT_ROLES } from "./roles"

/**
 * Client-safe: get permissions from the current org membership's public metadata.
 * This runs on the server; for client use the usePermissions hook.
 */
export async function getServerPermissions(): Promise<PermissionKey[]> {
  const { sessionClaims, orgId } = await auth()
  if (!orgId || !sessionClaims) return []

  // Clerk stores org membership metadata in sessionClaims.org_metadata
  const orgRole = (sessionClaims as Record<string, unknown>)["org_role"] as string | undefined
  const orgMetadata = (sessionClaims as Record<string, unknown>)["org_metadata"] as Record<string, unknown> | undefined

  // Try to get custom roles from org metadata
  const customRoles = orgMetadata?.["roles"] as RoleDefinition[] | undefined
  const roles = customRoles || DEFAULT_ROLES

  if (!orgRole) return []

  // Find the role that matches the org role
  const role = roles.find((r) => r.id === orgRole || r.name.toLowerCase().replace(/\s+/g, "-") === orgRole?.replace("org:", ""))
  return role?.permissions ?? []
}

/**
 * Server-side permission check. Throws an error if the user doesn't have the permission.
 * Use this in Server Actions and API Route Handlers.
 */
export async function requirePermission(permission: PermissionKey): Promise<void> {
  const { userId, orgId } = await auth()

  if (!userId) {
    throw new Error("UNAUTHORIZED: Not authenticated")
  }

  const permissions = await getServerPermissions()

  if (!permissions.includes(permission)) {
    throw new Error(`FORBIDDEN: Missing permission: ${permission}`)
  }
}

/**
 * Server-side multi-permission check. All permissions must be present.
 */
export async function requireAllPermissions(...permissions: PermissionKey[]): Promise<void> {
  const userPermissions = await getServerPermissions()
  for (const perm of permissions) {
    if (!userPermissions.includes(perm)) {
      throw new Error(`FORBIDDEN: Missing permission: ${perm}`)
    }
  }
}

/**
 * Server-side: check if user has a permission (returns boolean, doesn't throw).
 */
export async function hasPermission(permission: PermissionKey): Promise<boolean> {
  try {
    const permissions = await getServerPermissions()
    return permissions.includes(permission)
  } catch {
    return false
  }
}

