"use client"

import { useOrganization, useUser } from "@clerk/nextjs"
import { useMemo } from "react"
import type { PermissionKey } from "@/lib/auth/permissions"
import type { RoleDefinition } from "@/lib/auth/roles"
import { DEFAULT_ROLES } from "@/lib/auth/roles"

interface UsePermissionsReturn {
  can: (permission: PermissionKey) => boolean
  canAll: (...permissions: PermissionKey[]) => boolean
  canAny: (...permissions: PermissionKey[]) => boolean
  permissions: PermissionKey[]
  role: RoleDefinition | null
  isLoaded: boolean
}

export function usePermissions(): UsePermissionsReturn {
  const { user, isLoaded: userLoaded } = useUser()
  const { organization, membership, isLoaded: orgLoaded } = useOrganization()

  const isLoaded = userLoaded && orgLoaded

  const { permissions, role } = useMemo(() => {
    if (!isLoaded || !user) return { permissions: [] as PermissionKey[], role: null }

    // Get custom roles from org metadata or use defaults
    const orgMetadata = organization?.publicMetadata as { roles?: RoleDefinition[] } | undefined
    const availableRoles: RoleDefinition[] = orgMetadata?.roles ?? DEFAULT_ROLES

    // Get the user's role in the current org
    const memberRole = membership?.role // e.g. "org:admin", "org:manager"

    if (!memberRole) {
      // Check user's personal metadata for standalone permissions
      const userMeta = user.publicMetadata as { role?: string; permissions?: PermissionKey[] }
      if (userMeta?.permissions) {
        return { permissions: userMeta.permissions, role: null }
      }
      return { permissions: [] as PermissionKey[], role: null }
    }

    // Map clerk role (org:admin) to our role system
    const roleSlug = memberRole.replace("org:", "")
    const matchedRole = availableRoles.find(
      (r) => r.id === roleSlug || r.id === memberRole || r.name.toLowerCase().replace(/\s+/g, "-") === roleSlug
    )

    // Super admin / org:admin gets all permissions
    if (roleSlug === "admin" || memberRole === "org:admin") {
      const superAdmin = availableRoles.find((r) => r.id === "super-admin")
      if (superAdmin) {
        return { permissions: superAdmin.permissions, role: superAdmin }
      }
    }

    return {
      permissions: matchedRole?.permissions ?? [] as PermissionKey[],
      role: matchedRole ?? null,
    }
  }, [isLoaded, user, organization, membership])

  const can = useMemo(() => (permission: PermissionKey): boolean => {
    return permissions.includes(permission)
  }, [permissions])

  const canAll = useMemo(() => (...perms: PermissionKey[]): boolean => {
    return perms.every((p) => permissions.includes(p))
  }, [permissions])

  const canAny = useMemo(() => (...perms: PermissionKey[]): boolean => {
    return perms.some((p) => permissions.includes(p))
  }, [permissions])

  return { can, canAll, canAny, permissions, role, isLoaded }
}

